Translate("ptBR", "undercity", {
	title = "Cidade Baixa",
	sections = {
		{
			title = "Resumo",
			text = [=[A Cidade Baixa fica sob as ruínas da {link:capital-city}Cidade Capital{/link} de {link:lordaeron}Lordaeron{/link}, no leste das {link:tirisfal-glades}Clareiras de Tirisfal{/link}. É a capital dos {link:forsaken}Renegados{/link} e a sede de sua rainha, {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. Seus salões foram escavados nos esgotos, criptas e catacumbas da velha cidade. Um lodo verde corre por seus canais, morcegos circulam por suas abóbadas, e seus quatro grandes bairros cercam um pátio central onde os Renegados negociam, tramam e preparam seus venenos. Nenhuma cidade do mundo é mais estranha, e poucas são mais bem defendidas.]=],
		},
		{
			title = "Origens",
			text = [=[Os primeiros túneis não foram cavados pelos {link:forsaken}Renegados{/link}. Depois que o Príncipe {link:arthas-menethil}Arthas Menethil{/link} matou o pai e saqueou a capital, ele pretendia governar o norte a partir de suas ruínas, e pôs o {link:scourge}Flagelo{/link} para aprofundar as criptas sob a cidade. Então o Lich Rei o chamou a Nortúndria, e a obra ficou inacabada. Quando o domínio do Lich Rei enfraqueceu, {link:sylvanas-windrunner}Sylvanas{/link} se libertou. Com o senhor do medo {link:varimathras}Varimathras{/link} preso a seu serviço, ela derrubou os demônios que queriam governar o reino arruinado, e tomou a capital caída para seu povo.

Os Renegados desceram. Reuniram os mortos de livre-arbítrio das ruínas de cima e os trouxeram para baixo para engrossar suas fileiras. Um pedreiro chamado Bernd, resgatado das ruínas, liderou os trabalhadores que moldaram os novos salões. Comerciantes goblins vieram em seguida e abriram as primeiras lojas do {link:trade-quarter}Trade Quarter{/link}. Os mortos de {link:lordaeron}Lordaeron{/link} tinham um lar de novo.]=],
		},
		{
			title = "O Presente",
			text = [=[A Cidade Baixa está completa, ou quase, e está cheia. Do {link:royal-quarter}Royal Quarter{/link}, {link:sylvanas-windrunner}Sylvanas{/link} trava guerra contra o {link:scourge}Flagelo{/link} e contra a {link:scarlet-crusade}Cruzada Escarlate{/link}. {link:varimathras}Varimathras{/link} comanda a defesa da cidade. No {link:the-apothecarium}Apothecarium{/link}, a {link:royal-apothecary-society}Real Sociedade de Boticários{/link} trabalha numa nova praga que a Dama Sombria ordenou. A cidade se uniu à {link:horde}Horda{/link} e recebe seus orcs, trolls e taurens, que a acham inquietante. Seu povo também se lembra de um terror recente. Não faz muito tempo, a necrópole {red:naxxramas}Naxxramas{/red} veio contra a cidade, e os {link:forsaken}Renegados{/link} a combateram na superfície das ruínas. Muitos tombaram ali, entre eles o capitão da Guarda da Morte.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os {link:forsaken}Renegados{/link}.{/b} Cidadãos, soldados e estudiosos do reino morto, muitos deles o povo da própria capital de {link:lordaeron}Lordaeron{/link}.
• {b}A {link:royal-apothecary-society}Real Sociedade de Boticários{/link}.{/b} Os químicos do {link:the-apothecarium}Apothecarium{/link}, com seus prisioneiros e suas abominações.
• {b}A Guarda da Morte e a Guarda Temível Real.{/b} Os soldados da cidade e os guardas do trono.
• {b}Goblins.{/b} Comerciantes e barbeiros que vieram quando a cidade era jovem e se deram muito bem desde então.
• {b}As patrulheiras sombrias.{/b} Elfas mortas-vivas que servem à Dama Sombria e se lembram de {link:quel-thalas}Quel'Thalas{/link}.]=],
		},
		{
			title = "História",
			text = [=[• {b}A {link:capital-city}Cidade Capital{/link}.{/b} Durante séculos, os reis de {link:lordaeron}Lordaeron{/link} governaram do palácio acima.
• {b}A Queda.{/b} Na {link:third-war}Terceira Guerra{/link}, {link:arthas-menethil}Arthas{/link} assassinou o Rei {link:terenas-menethil}Terenas Menethil{/link} e entregou a cidade ao {link:scourge}Flagelo{/link}. Essa foi a {link:fall-of-lordaeron}Queda de Lordaeron{/link}.
• {b}Os Túneis.{/b} O Flagelo começou a escavar catacumbas sob a cidade, e as deixou inacabadas.
• {b}A Fundação.{/b} {link:sylvanas-windrunner}Sylvanas{/link} e seus {link:forsaken}Renegados{/link} tomaram as ruínas e construíram sua cidade embaixo.
• {b}O Ataque Escarlate.{/b} Cerca de um ano depois da fundação, a {link:scarlet-crusade}Cruzada Escarlate{/link} invadiu a Cidade Baixa rompendo suas muralhas, e a Guarda da Morte a expulsou.
• {b}A Necrópole.{/b} Quando Naxxramas atacou, os Renegados e a {link:argent-dawn}Aurora Argêntea{/link} a combateram juntos acima da cidade.]=],
		},
		{
			title = "Saberes da Cidade",
			text = [=[• Os {link:forsaken}Renegados{/link} dizem que o goblin {link:glix-xizzix}Glix Xizzix{/link} alimentou os famintos da cidade e armou seus defensores na guerra contra o {link:scourge}Flagelo{/link}. Glix é quem mais diz isso.
• Perto do trono da Dama Sombria, às vezes se ouve um lamento dos altos elfos. É uma canção da terra natal caída que ela um dia defendeu.]=],
		},
	},
})

Translate("ptBR", "trade-quarter", {
	title = "Trade Quarter",
	sections = {
		{
			title = "Resumo",
			text = [=[O Trade Quarter é o coração da {link:undercity}Cidade Baixa{/link}, um grande anel de salões no fundo dos elevadores que descem das ruínas de cima. Aqui ficam o banco, a casa de leilões, a estalagem e as bancas de cem mercadores. O Superintendente Real mantém aqui o censo da cidade. Um goblin corta o cabelo dos mortos. Mendigos esperam nos cantos por restos, e boticários passam apressados por eles a serviço da Dama Sombria. Todo visitante da Cidade Baixa passa primeiro pelo Trade Quarter.]=],
		},
	},
})

Translate("ptBR", "the-apothecarium", {
	title = "The Apothecarium",
	aliases = { "Apothecarium" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Apothecarium é o domínio da {link:royal-apothecary-society}Real Sociedade de Boticários{/link}. Seus químicos o chamam de órgão mais vital da {link:undercity}Cidade Baixa{/link}. Do outro lado de um canal de lodo verde, em abóbadas cheias de tonéis borbulhantes e prisioneiros engaiolados, eles estudam os venenos de todas as terras e preparam a nova praga que {link:sylvanas-windrunner}a Dama Sombria{/link} exigiu. O {link:master-apothecary-faranell}Mestre Boticário Faranell{/link} governa aqui. Seus assistentes costuram abominações com quaisquer corpos que consigam encontrar, e um deles transforma cativos em feras. Os alquimistas da cidade também ensinam seu ofício nestes salões, e poções que não sobrevivem a uma longa viagem são trazidas para cá às pressas.]=],
		},
	},
})

Translate("ptBR", "magic-quarter", {
	title = "Magic Quarter",
	sections = {
		{
			title = "Resumo",
			text = [=[O Magic Quarter é o salão dos magos e bruxos da {link:undercity}Cidade Baixa{/link}. Alguns deles estudaram o arcano em {link:dalaran}Dalaran{/link} antes da praga e não perderam nada de seu saber na morte. O mais poderoso deles é o mago {link:bethor-iceshard}Bethor Iceshard{/link}. Aqui também ficam os mestres de portais da cidade e uma banshee que ensina as artes do mago. Os {link:forsaken}Renegados{/link} deste bairro são astutos e pacientes, e procuram todo estudioso que se libertou do Lich Rei.]=],
		},
	},
})

Translate("ptBR", "war-quarter", {
	title = "War Quarter",
	sections = {
		{
			title = "Resumo",
			text = [=[O War Quarter fica no noroeste da {link:undercity}Cidade Baixa{/link}. É a base dos militares {link:forsaken}Renegados{/link} e o lar dos sacerdotes da cidade, que agora servem às sombras. Aqui a Cidade Baixa treina seus combatentes. Seus salões ressoam com o choque das lâminas de treino e com os martelos dos ferreiros. Os guerreiros aprendem aqui seu ofício, um mestre de armas ensina todo tipo de armamento, e os ferreiros da cidade trabalham em suas forjas. Nestes dias, até um instrutor de paladinos pode ser encontrado em seus salões, algo que muitos Renegados um dia teriam julgado impossível.]=],
		},
	},
})

Translate("ptBR", "royal-quarter", {
	title = "Royal Quarter",
	sections = {
		{
			title = "Resumo",
			text = [=[O Royal Quarter fica na parte mais funda da {link:undercity}Cidade Baixa{/link}, abaixo da sala do trono arruinada onde {link:arthas-menethil}Arthas{/link} assassinou o pai. Aqui {link:sylvanas-windrunner}Sylvanas Windrunner{/link} mantém sua corte. Seus guardas temíveis ladeiam a câmara, e {link:varimathras}Varimathras{/link} está a seu lado. Seus campeões vêm aqui receber suas ordens, e aqui os capitães da {link:horde}Horda{/link} reúnem combatentes para os campos de batalha distantes de {link:alterac-mountains}Alterac{/link}, {link:arathi-highlands}Arathi{/link} e {link:ashenvale}Vale Gris{/link}. A banshee Sharlindra também flutua pela câmara. O paladino Renegado {link:morbin-lightbane}Morbin Lightbane{/link} espera por perto, reunindo o que seu povo precisa para remendar seus mortos.]=],
		},
	},
})

Translate("ptBR", "sylvanas-windrunner", {
	title = "Sylvanas Windrunner",
	subtitle = "A Rainha Banshee",
	found = "O Royal Quarter da Cidade Baixa",
	hint = [=[Procure a rainha dos Renegados no salão mais profundo da Cidade Baixa.]=],
	allegiance = "Renegados · Horda · antes, os Andarilhos de Quel'Thalas",
	aliases = { "Sylvanas", "Lady Sylvanas Windrunner", "Lady Sylvanas", "a Dama Sombria", "a Rainha Banshee" },
	sections = {
		{
			title = "Resumo",
			text = [=[Sylvanas Windrunner é a rainha dos {link:forsaken}Renegados{/link}. Em vida, foi a General-patrulheira de {link:quel-thalas}Quel'Thalas{/link}, a comandante de seus patrulheiros. Morreu defendendo sua terra natal contra o {link:scourge}Flagelo{/link}, e {link:arthas-menethil}Arthas{/link} a ergueu como banshee para servi-lo. Ela se libertou, e conduziu os mortos-vivos de {link:lordaeron}Lordaeron{/link} para fora do domínio do Lich Rei. Seu povo a chama de Dama Sombria. Eles lhe obedecem, e muitos a amam.]=],
		},
		{
			title = "Importância",
			text = [=[Ninguém fez mais para dar um futuro aos mortos de {link:lordaeron}Lordaeron{/link}. Sylvanas fez deles um povo, deu-lhes um nome e uma cidade, e os trouxe para a {link:horde}Horda{/link}. Também os tornou temidos. Sua guerra contra {link:arthas-menethil}Arthas{/link} é pessoal. Sua guerra contra os vivos é mais difícil de explicar, e ela não tenta explicá-la.]=],
		},
		{
			title = "Feitos",
			text = [=[• Liderou os patrulheiros de {link:quel-thalas}Quel'Thalas{/link} contra o {link:scourge}Flagelo{/link} na {link:third-war}Terceira Guerra{/link}, e tombou diante de {link:arthas-menethil}Arthas Menethil{/link}.
• Recuperou sua vontade quando o poder do Lich Rei vacilou.
• Prendeu a seu serviço o senhor do medo {link:varimathras}Varimathras{/link} e derrubou os demônios que dominavam o reino arruinado.
• Tomou as ruínas da capital e construiu a {link:undercity}Cidade Baixa{/link} sob elas.
• Buscou aliados além de suas terras, e os {link:forsaken}Renegados{/link} se uniram à {link:horde}Horda{/link}.
• Ordenou à {link:royal-apothecary-society}Real Sociedade de Boticários{/link} que preparasse uma nova praga, mais mortal que qualquer outra em {link:azeroth}Azeroth{/link}, para destruir o Flagelo.]=],
		},
	},
	chapters = {
		{
			title = "A Fundação",
			hint = [=[Descubra como os mortos de Lordaeron encontraram um lar sob as ruínas.]=],
			text = [=[Quando os {link:forsaken}Renegados{/link} desceram pela primeira vez sob a capital arruinada, eram poucos. Sylvanas enviou seus servos às ruínas para encontrar os mortos que haviam despertado e trazê-los para baixo para se juntarem a seu povo. Deu a cada um deles um lugar e um dever. Os que lhe juraram lealdade nunca mais ficaram sozinhos.]=],
		},
		{
			title = "Uma Nova Praga",
			hint = "Ajude os boticários de Montalvo na obra da Dama Sombria.",
			text = [=[Sylvanas acredita que as artes dos boticários, unidas à nova magia dos {link:forsaken}Renegados{/link}, guardam a chave da ruína de {link:arthas-menethil}Arthas{/link}. Ela desafiou seus químicos a preparar uma praga que destrua o exército dele. O que mais essa praga poderia destruir, ela não disse.]=],
		},
		{
			title = "Os Paladinos de Tyr's Watch",
			hint = "Leve a cabeça de um traidor à Dama Sombria.",
			text = [=[Os {link:forsaken}Renegados{/link} lembram a Luz como a arma que os vivos voltaram contra eles. Quando {link:danitha-morr}Danitha Morr{/link} lhe enviou a cabeça de um paladino Maculado que assassinara Renegados, Sylvanas a recebeu sem calor. Não duvidava da boa-fé de Danitha, disse. Simplesmente esperava mais loucuras assim, e avisou à ordem que um dia poderia decidir que não valia a pena mantê-la.]=],
		},
		{
			title = "Seu Campeão",
			hint = "Prove seu valor à Rainha Banshee.",
			text = [=[Entre os primeiros campeões de Sylvanas estava o patrulheiro {link:nathanos-blightcaller}Nathanos{/link}, agora chamado de Blightcaller. Ele vive sozinho no {link:the-marris-stead}Sítio dos Marris{/link}, nas {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}, e caça ali o {link:scourge}Flagelo{/link} e a {link:alliance}Aliança{/link}. Sylvanas envia a ele apenas seus servos mais calejados.]=],
		},
	},
	mentions = {
		{ text = "Despertar Brusco" },
		{ text = "Uma Nova Praga" },
		{ text = "Um Sinal de Boa-fé" },
		{ text = "O Campeão da Rainha Banshee" },
	},
	bonds = {
		{ id = "varimathras", name = "Varimathras", note = "seu servo preso a ela" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu assassino" },
		{ id = "dark-ranger-anya", name = "Patrulheira Sombria Anya", note = "uma patrulheira leal" },
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "jurou-lhe lealdade" },
		{ id = "master-apothecary-faranell", name = "Mestre Boticário Faranell", note = "prepara sua praga" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "lidera uma ordem da qual ela desconfia" },
	},
})

Translate("ptBR", "varimathras", {
	title = "Varimathras",
	subtitle = "Tenente da Dama Sombria",
	found = "O Royal Quarter da Cidade Baixa, ao lado da Dama Sombria",
	hint = [=[Fale com o senhor do medo que está ao lado da Rainha Banshee.]=],
	allegiance = "Renegados · antes, a Legião Ardente",
	sections = {
		{
			title = "Resumo",
			text = [=[Varimathras é um senhor do medo, um dos nathrezim da {link:burning-legion}Legião Ardente{/link}. Depois da queda de {link:archimonde}Archimonde{/link}, ele e seus irmãos tentaram tomar para si o reino arruinado de {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas Windrunner{/link} o fez prisioneiro e lhe deu uma escolha: servi-la, ou morrer. Ele escolheu servir. Ajudou-a a derrubar seus próprios irmãos, e desde então está a seu lado, no salão mais profundo de sua cidade.]=],
		},
		{
			title = "Importância",
			text = [=[Varimathras é o tenente da Dama Sombria e o senhor da defesa da {link:undercity}Cidade Baixa{/link}. Seus agentes e soldados percorrem {link:tirisfal-glades}Tirisfal{/link}, e ele cuida dos inimigos mais próximos de casa enquanto sua rainha vigia o norte. Que um demônio da Legião sirva aos {link:forsaken}Renegados{/link} é um fato estranho. Muitos Renegados preferem não pensar nisso. Os que pensam sabem apenas o que viram: que ele serviu sua rainha sem falhar desde o dia em que ela o poupou, e que despreza a humanidade tanto quanto ela. Seus soldados ouvem que ele mesmo cuida para que a raça humana seja varrida de {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Jurou lealdade a {link:sylvanas-windrunner}Sylvanas{/link} e a ajudou a derrubar os senhores do medo que governavam o reino arruinado.
• Comanda a defesa da {link:undercity}Cidade Baixa{/link}.
• Dirige a guerra contra a {link:scarlet-crusade}Cruzada Escarlate{/link} e quer seus líderes mortos.
• Recebe os relatórios dos Sicários, os espiões da Dama Sombria.
• Caça os agentes do {link:scourge}Flagelo{/link} muito além de {link:lordaeron}Lordaeron{/link}.
• Busca os livros de feitiços da Searing Blade, escondidos nas cavernas sob {link:orgrimmar}Orgrimmar{/link}, para uso da Dama Sombria.]=],
		},
	},
	chapters = {
		{
			title = "As Formigas Vermelhas",
			hint = "Ataque o coração da Cruzada Escarlate.",
			text = [=[Enquanto {link:sylvanas-windrunner}a Dama Sombria{/link} cuida do avanço do Lich Rei no norte, Varimathras trata de assuntos mais próximos de casa. Ele chama a {link:scarlet-crusade}Cruzada Escarlate{/link} de o espinho mais afiado no flanco dos {link:forsaken}Renegados{/link}, e quer a {link:high-inquisitor-whitemane}Alta Inquisidora Whitemane{/link} e seus principais tenentes mortos nos salões do {link:scarlet-monastery}Monastério Escarlate{/link}.]=],
		},
		{
			title = "Os Sicários",
			hint = "Descubra as tramas dos senhores de Alterac.",
			text = [=[Os Sicários descobriram que a {link:syndicate}Camarilha{/link} era formada pelos antigos senhores de {link:alterac-mountains}Alterac{/link}, os traidores da {link:second-war}Segunda Guerra{/link}. Seu relatório chegou a Varimathras. Ele fica satisfeito com trabalhos assim, e os recompensa.]=],
		},
		{
			title = "Uma Aliança Profana",
			hint = "Encontre o embaixador do Flagelo enviado aos javatuscos.",
			text = [=[O Lich Rei enviou um embaixador chamado {link:ambassador-malcin}Malcin{/link} aos javatuscos do {link:razorfen-downs}Urzal dos Mortos{/link}, e alguns dos javatuscos começaram a mostrar os sinais da praga. Varimathras queria o embaixador morto e sua missão fracassada. Quando Malcin tombou, o senhor do medo enviou os agradecimentos da Dama Sombria.]=],
		},
	},
	mentions = {
		{ text = "Para o {link:scarlet-monastery}Monastério Escarlate{/link}" },
		{ text = "Os Sicários" },
		{ text = "Uma {link:alliance}Aliança{/link} Profana" },
		{ text = "O Poder de Destruir..." },
		{ text = "Prova de Morte" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sua rainha" },
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "formou a guarda da cidade por ordem dele" },
	},
})

Translate("ptBR", "master-apothecary-faranell", {
	title = "Mestre Boticário Faranell",
	subtitle = "Senhor do Apothecarium",
	found = "O Apothecarium",
	hint = "Procure o mestre boticário nas abóbadas do Apothecarium.",
	allegiance = "Real Sociedade de Boticários",
	aliases = { "Faranell" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Mestre Boticário Faranell governa o {link:the-apothecarium}Apothecarium{/link}. Ele supervisiona a obra mais ambiciosa da {link:royal-apothecary-society}Real Sociedade de Boticários{/link}: a nova praga que {link:sylvanas-windrunner}a Dama Sombria{/link} ordenou, uma doença para arruinar o {link:scourge}Flagelo{/link} e, com o tempo, os vivos. Seus colegas lhe enviam suas descobertas de {link:silverpine-forest}Pinhaprata{/link}, de {link:hillsbrad-foothills}Eira dos Montes{/link} e de mais além. Ele fala de seu trabalho com uma alegria que assusta quem o compreende.]=],
		},
		{
			title = "Importância",
			text = [=[Faranell é onde o saber da Sociedade se reúne. Ele também faz abominações para {link:sylvanas-windrunner}a Dama Sombria{/link}, e não se furta a uma piada às custas de suas cobaias.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estuda a praga antiga que um dia matou a vida do Espelho de {link:lordaeron}Lordaeron{/link}.
• Acrescenta seu próprio coloide de decomposição às misturas de seus colegas.
• Submete os mortos costurados à vontade da Dama Sombria.]=],
		},
	},
	chapters = {
		{
			title = "Uma Receita para a Morte",
			hint = "Leve à Cidade Baixa as descobertas dos boticários.",
			text = [=[Um boticário chamado Berard havia estudado uma praga antiga do Espelho de {link:lordaeron}Lordaeron{/link} antes que a maldição do feiticeiro {link:archmage-arugal}Arugal{/link} lhe tomasse a mente. Seu diário sobreviveu. Faranell retomou o trabalho, e disse a quem o trouxe que a Sociedade estava à beira de algo grandioso.]=],
		},
		{
			title = "Tormento sem Fim",
			hint = "Encontre quem conhece a abominação de cabeça emprestada.",
